        lv = range(self.nlayers) if (dr > 0 or len(lays) == self.nlayers) else lays
        for l in lv:
            mark_disk(self.occV[l], g, pos.x, pos.y, rv, nid)

    def mark_track(self, x1, y1, x2, y2, layer, width, nid):
        g = self.g
        for w in self.wgroups:
            r = width / 2.0 + self.clear + w / 2.0
            mark_capsule(self.occT[w][layer], g, x1, y1, x2, y2, r, nid)
        rv = width / 2.0 + self.clear + self.via_d / 2.0
        mark_capsule(self.occV[layer], g, x1, y1, x2, y2, rv, nid)

    def mark_via(self, x, y, nid):
        g = self.g
        for w in self.wgroups:
            r = self.via_d / 2.0 + max(self.clear, self.hole_clear) + w / 2.0
            for l in range(self.nlayers):
                mark_disk(self.occT[w][l], g, x, y, r, nid)
        rv = self.via_d / 2.0 + max(self.clear, self.h2h) + self.via_d / 2.0
        for l in range(self.nlayers):
            mark_disk(self.occV[l], g, x, y, rv, nid)

    # ---- free maps
    def freemap(self, net):
        nid = self.netid[net]
        w = self.netwidth[net]
        out = []
        for l in range(self.nlayers):
            a = self.occT[w][l]
            v = self.occV[l]
            f = ((a == 0) | (a == nid)).astype(np.uint8)
            f |= (((v == 0) | (v == nid)).astype(np.uint8) << 1)
            out.append(f.tobytes())
        return out

    # ---- pad cells
    def pad_cells(self, p):
        """grid cells (per layer) whose centre is inside the pad."""
        g = self.g
        pos = p["pos"]
        sx, sy = p["size"][0], p["size"][1]
        sh = p["shape"]
        ang = p["ang"]
        ext = max(sx, sy) / 2.0 + g.p
        wd = win(g, pos.x - ext, pos.x + ext, pos.y - ext, pos.y + ext)
        cells = []
        if not wd:
            return cells
        a, b, c, d = wd
        xs = (g.x0 + np.arange(a, b + 1) * g.p).astype(np.float64) - pos.x
        ys = (g.y0 + np.arange(c, d + 1) * g.p).astype(np.float64) - pos.y
        X = xs[None, :] + 0 * ys[:, None]
        Y = ys[:, None] + 0 * xs[None, :]
        shrink = min(sx, sy) * 0.5
        if sh == pcbnew.PAD_SHAPE_CIRCLE:
            m = (X ** 2 + Y ** 2) <= (sx / 2.0) ** 2
        else:
            rad = math.radians(ang)
            ca, sa = math.cos(rad), math.sin(rad)
            lx = X * ca + Y * sa
            ly = -X * sa + Y * ca
            m = (np.abs(lx) <= sx / 2.0) & (np.abs(ly) <= sy / 2.0)
        ii, jj = np.nonzero(m)
        for k in range(len(ii)):
            cells.append((c + ii[k]) * g.W + (a + jj[k]))
        if not cells:
            cells.append(g.cy(pos.y) * g.W + g.cx(pos.x))
        return cells


def main():
    src, dst = sys.argv[1], sys.argv[2]
    R = Router(src)
    pcbnew.SaveBoard(dst, R.board)
    R.setup_grid()
    R.build_static()
    from engine import run
    run(R, dst)


