        w = R.netwidth[net]
        items = []
        pts = []
        for nd in path:
            lay = nd // N
            i = nd - lay * N
            pts.append((lay, g.wx(i % g.W), g.wy(i // g.W)))
        # anchors
        if anch_s:
            l0, x0, y0 = pts[0]
            if (x0, y0) != anch_s:
                pts.insert(0, (l0, anch_s[0], anch_s[1]))
        if anch_d:
            l1, x1, y1 = pts[-1]
            if (x1, y1) != anch_d:
                pts.append((l1, anch_d[0], anch_d[1]))
