        sa, anchA = self.node_sets(net, ua, pa, freeb)
        sb, anchB = self.node_sets(net, ub, pb, freeb)
        if not sa or not sb:
            return None
        tn = self.tree_nodes(net)
        srcs = sa | (tn & set())
        # add existing copper of this net as extra sources (helps multi-pad nets)
        extra = self.tree_nodes(net)
        srcs = set(sa)
        anchors = dict(anchA)
        for nd in extra:
            if nd not in srcs:
                srcs.add(nd)
                anchors[nd] = None
