            return None
        aS = anchors.get(path[0])
        aD = anchB.get(path[-1])
        return self.path_items(net, path, aS, aD)


def run(R, dst):
    eng = Engine(R, dst)
    g = R.g
    R.via_cost = 2.0 * MM
    eng.paduuid = {}
    for p in R.pads:
        try:
            eng.paduuid[p["obj"].m_Uuid.AsString()] = p
        except Exception:
            pass
    edges = eng.ratsnest(R.src)
    if not edges:
        # fall back: MST over pads of each net
        edges = []
        for net, pads in R.netpads.items():
            if len(pads) < 2:
                continue
            pts = [(p["pos"].x, p["pos"].y, p) for p in pads]
            used = [0]
            rest = list(range(1, len(pts)))
            while rest:
                best = None
                for i in used:
                    for j in rest:
                        d = (pts[i][0] - pts[j][0]) ** 2 + (pts[i][1] - pts[j][1]) ** 2
                        if best is None or d < best[0]:
                            best = (d, i, j)
                _, i, j = best
                used.append(j)
                rest.remove(j)
                edges.append((net, pts[i][2]["obj"].m_Uuid.AsString(), pts[j][2]["obj"].m_Uuid.AsString(),
                              (pts[i][0], pts[i][1]), (pts[j][0], pts[j][1])))
    # order: group by net, nets by total length
    bynet = {}
    for e in edges:
        bynet.setdefault(e[0], []).append(e)
    def elen(e):
        return math.hypot(e[3][0] - e[4][0], e[3][1] - e[4][1])
    order = sorted(bynet.keys(), key=lambda n: sum(elen(e) for e in bynet[n]))
    for n in order:
        bynet[n].sort(key=elen)

    failed = []
    done = 0
    for net in order:
        if left() < 60:
            break
        for e in bynet[net]:
            items = eng.route_edge(net, e, 1.0)
            if items is None:
                items = eng.route_edge(net, e, 2.0)
            if items is None:
                failed.append(e)
            else:
                eng.add_items(net, items)
                done += 1
    eng.save()
    sys.stderr.write("pass1 routed %d/%d failed %d t=%.1f\n" % (done, len(edges), len(failed), time.time() - T0))
    sys.stderr.flush()
    improve(eng, edges, failed)


def improve(eng, edges, failed):
    R = eng.R
    best_score = None
    rounds = 0
    while left() > 70 and rounds < 8:
        rounds += 1
        rep = run_drc(eng.dst, eng.work)
        if rep is None:
            return
        bad = set()
        for v in rep.get("violations", []):
            if v.get("severity") != "error" or v.get("type") not in COUNTED:
                continue
            for it in v.get("items", []):
                d = it.get("description", "")
                if "[" in d and "]" in d:
                    nm = d[d.index("[") + 1:d.rindex("]")]
                    nm = eng.plain.get(nm, nm)
                    if nm in eng.netitems:
                        bad.add(nm)
        openedges = eng.ratsnest_from(rep)
        openn = set(e[0] for e in openedges)
        score = len(bad) + len(openn)
        sys.stderr.write("round %d: bad=%d open=%d t=%.1f\n" % (rounds, len(bad), len(openn), time.time() - T0))
        sys.stderr.flush()
        if not bad and not openedges:
            return
        # rip up bad nets entirely, retry them; retry open edges with more effort
        for n in bad:
            eng.netitems.pop(n, None)
        eng.rebuild_occ()
        todo = []
        for n in bad:
            for e in eng.bynet.get(n, []):
                todo.append(e)
        for e in openedges:
            if e[0] not in bad:
                todo.append(e)
        todo.sort(key=lambda e: math.hypot(e[3][0] - e[4][0], e[3][1] - e[4][1]))
        progress = False
        for e in todo:
            if left() < 55:
                break
            items = eng.route_edge(e[0], e, 2.0, via_cost_mul=1.0 + 0.3 * rounds)
            if items is not None:
                eng.add_items(e[0], items)
                progress = True
        eng.save()
        if not progress:
            return

