        w = R.netwidth[net]
        items = []
        pts = []
        for nd in path:
            lay = nd // N
            i = nd - lay * N
            pts.append((lay, g.wx(i % g.W), g.wy(i // g.W)))
        # anchors
        if anch_s:
            l0, x0, y0 = pts[0]
            if (x0, y0) != anch_s:
                pts.insert(0, (l0, anch_s[0], anch_s[1]))
        if anch_d:
            l1, x1, y1 = pts[-1]
            if (x1, y1) != anch_d:
                pts.append((l1, anch_d[0], anch_d[1]))
        # compress
        k = 0
        while k < len(pts) - 1:
            lay, x, y = pts[k]
            lay2, x2, y2 = pts[k + 1]
            if lay2 != lay:
                items.append(('V', x, y))
                k += 1
                continue
            # extend while same direction
            dx, dy = x2 - x, y2 - y
            j = k + 1
            while j + 1 < len(pts):
