        # bounding box
        xs = [pa[0], pb[0]]
        ys = [pa[1], pb[1]]
        span = max(abs(pa[0] - pb[0]), abs(pa[1] - pb[1]))
        marg = int(max(6 * g.p, span * 0.45 * effort) + 8 * g.p * effort)
        bx0 = max(0, g.cx(min(xs) - marg))
        bx1 = min(g.W - 1, g.cx(max(xs) + marg))
