def improve(eng, edges, failed):
    R = eng.R
    best_score = None
    rounds = 0
    while left() > 70 and rounds < 8:
        rounds += 1
        rep = run_drc(eng.dst, eng.work)
        if rep is None:
            return
        bad = set()
        for v in rep.get("violations", []):
            if v.get("severity") != "error" or v.get("type") not in COUNTED:
                continue
            for it in v.get("items", []):
                d = it.get("description", "")
                if "[" in d and "]" in d:
                    nm = d[d.index("[") + 1:d.rindex("]")]
                    nm = eng.plain.get(nm, nm)
                    if nm in eng.netitems:
                        bad.add(nm)
        openedges = eng.ratsnest_from(rep)
        openn = set(e[0] for e in openedges)
        score = len(bad) + len(openn)
        sys.stderr.write("round %d: bad=%d open=%d t=%.1f\n" % (rounds, len(bad), len(openn), time.time() - T0))
        sys.stderr.flush()
        if not bad and not openedges:
            return
        # rip up bad nets entirely, retry them; retry open edges with more effort
        for n in bad:
            eng.netitems.pop(n, None)
        eng.rebuild_occ()
        todo = []
        for n in bad:
            for e in eng.bynet.get(n, []):
                todo.append(e)
        for e in openedges:
            if e[0] not in bad:
                todo.append(e)
        todo.sort(key=lambda e: math.hypot(e[3][0] - e[4][0], e[3][1] - e[4][1]))
        progress = False
        for e in todo:
            if left() < 55:
                break
            items = eng.route_edge(e[0], e, 2.0, via_cost_mul=1.0 + 0.3 * rounds)
            if items is not None:
                eng.add_items(e[0], items)
                progress = True
        eng.save()
        if not progress:
            return

